import numpy as np


class LinkPredictor:
    """Link prediction using GCN embeddings and inner product decoder."""

    def __init__(self, input_dim, hidden_dim, embed_dim):
        self.W1 = np.random.randn(input_dim, hidden_dim) * 0.01
        self.W2 = np.random.randn(hidden_dim, embed_dim) * 0.01

    def encode(self, A_norm, X):
        H = np.maximum(0, A_norm @ X @ self.W1)
        Z = A_norm @ H @ self.W2
        return Z

    def decode(self, Z, edge_index):
        src, dst = edge_index
        probs = np.sum(Z[src] * Z[dst], axis=1)
        probs = self.sigmoid(probs)
        return probs

    def negative_sampling(self, edge_index, num_nodes, num_neg):
        pos_set = set(zip(edge_index[0], edge_index[1]))
        neg_edges = []
        while len(neg_edges) < num_neg:
            src = np.random.randint(0, num_nodes)
            dst = np.random.randint(0, num_nodes)
            if (src, dst) not in pos_set and src != dst:
                neg_edges.append((src, dst))
        return np.array(neg_edges).T

    def compute_loss(self, Z, pos_edges, neg_edges):
        pos_probs = np.clip(self.decode(Z, pos_edges), 1e-7, 1 - 1e-7)
        neg_probs = np.clip(self.decode(Z, neg_edges), 1e-7, 1 - 1e-7)
        pos_loss = -np.mean(np.log(pos_probs))
        neg_loss = -np.mean(np.log(1 - neg_probs))
        return pos_loss + neg_loss

    def sigmoid(self, x):
        return np.where(x >= 0, 1 / (1 + np.exp(-x)), np.exp(x) / (1 + np.exp(x)))
